#!name=Reddit
#!desc=某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思
#!homepage=https://github.com/fmz200/wool_scripts
#!icon=https://raw.githubusercontent.com/fmz200/wool_scripts/main/icons/gif/naisi-01.gif
#!raw-url=https://github.com/fmz200/wool_scripts/raw/main/Loon/plugin/split/partR/Reddit.lpx
#!tg-channel=https://t.me/inaisi
#!date=2026-11-11 21:17:23
#############################################


[Argument]
reddit_enable = switch,true,false,tag=Reddit-脚本开关

[Script]
# 过滤推广 关NSFW提示 感谢【xream】分享
response if ${url} ~= /^https?:\/\/gql(-fed)?\.reddit\.com/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/reddit.js") with enable=${reddit_enable}, tag="reddit", timeout=60, requires_body=true

[MITM]
hostname = gql.reddit.com, gql-fed.reddit.com
